import{_ as a,o as s,c as o,a2 as t}from"./chunks/framework.CdjpmwdR.js";const l="/assets/image-1653875255217-0.DLUkC6WM.png",u=JSON.parse('{"title":"Mesh-Shaped 学习复盘：扩张与聚焦的平衡","description":"两个月学习实验的复盘：识别真正带来能力增量的做法、剔除制造忙碌感的行为，并讲述如何把发散探索收敛为可执行主线。","frontmatter":{"category":"mesh","date":"2022-03-01","title":"Mesh-Shaped 学习复盘：扩张与聚焦的平衡","description":"两个月学习实验的复盘：识别真正带来能力增量的做法、剔除制造忙碌感的行为，并讲述如何把发散探索收敛为可执行主线。","tags":["mesh","架构设计","工程实践"],"image":"/blogs/assets/202203-mesh-shaped-recap/image-1653875255217-0.png"},"headers":[],"relativePath":"blogs/2022/202203-mesh-shaped-recap.md","filePath":"blogs/2022/202203-mesh-shaped-recap.md"}'),h={name:"blogs/2022/202203-mesh-shaped-recap.md"};function r(i,e,p,n,d,c){return s(),o("div",null,[...e[0]||(e[0]=[t('<p>过去两个月，我用 Logseq 驱动了一次“Mesh-Shaped”学习实验。输入量确实上来了，但执行质量并不稳定。这里做一次阶段复盘：保留有效动作，收敛无效消耗。</p><h2 id="good-achievements" tabindex="-1">Good achievements <a class="header-anchor" href="#good-achievements" aria-label="Permalink to &quot;Good achievements&quot;">​</a></h2><ul><li>阅读了 3 本书（粗读）</li><li>阅读了 40+ 篇 Blog/文档，100+篇笔记（长短不一）</li><li>整理并复习了 DDD、Cloud-Native 的知识图谱</li><li>持续的贡献开源代码</li></ul><h2 id="less-well" tabindex="-1">Less well <a class="header-anchor" href="#less-well" aria-label="Permalink to &quot;Less well&quot;">​</a></h2><ul><li>一部分“碎片学习”是无效的</li><li>知识焦虑越来越重</li><li>OKR 优先级和权重失真</li></ul><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to &quot;Why&quot;">​</a></h2><p>在完成了规划已久的<a href="./../2022/202203-mesh-shaped-cloud-native-developer">“Mesh-Shaped”</a>设定之后，这一宏大愿景给了我非常强的信心和动力投身到 “mesh” 式的学习中。借助 Logseq 等工具，我把所关注的公众号、参与的技术群群、关注的社交网络中的大佬，都安排进了我的“knowledge pipeline” —— 通过摘抄、截图、总结把这些知识收集了起来。从编程语言的 tips、到云原生的发展前景、到架构模式的建立、到开源商业的市场逻辑，随着时间的推移，涉及的知识域越来越广。</p><p>但当知识域扩展到陌生领域时，问题暴露得很快：摘抄不等于理解，收藏不等于掌握。 我曾用 3 天才完成预估 10 小时的 GCP ML Fundamental 学习，这让我意识到：新领域学习需要连续深度时间，不适合靠碎片时间硬拼。</p><h3 id="一部分-碎片学习-是无效的" tabindex="-1">一部分“碎片学习”是无效的 <a class="header-anchor" href="#一部分-碎片学习-是无效的" aria-label="Permalink to &quot;一部分“碎片学习”是无效的&quot;">​</a></h3><p>复盘后我确认了一点：不少“学习动作”只是信息搬运。</p><p>碎片学习适合查漏补缺，不适合从 0 到 1 建模。对已有领域（如 DDD、面向对象）它能提升理解密度；对陌生领域它常常只会制造“我在学习”的错觉。</p><p>很多被我收藏的“碎片”，本质上只是焦虑驱动的囤积，并不会自然转化为能力。</p><h3 id="知识焦虑越来越重" tabindex="-1">知识焦虑越来越重 <a class="header-anchor" href="#知识焦虑越来越重" aria-label="Permalink to &quot;知识焦虑越来越重&quot;">​</a></h3><p>不设边界地阅读，直接带来知识焦虑。什么都想知道，最后往往什么都不成体系。</p><h3 id="okr-优先级和权重失真" tabindex="-1">OKR 优先级和权重失真 <a class="header-anchor" href="#okr-优先级和权重失真" aria-label="Permalink to &quot;OKR 优先级和权重失真&quot;">​</a></h3><p>碎片任务叠加后，主线 OKR 被持续挤压。我还一度尝试“并发推进”多个目标，结果是典型的上下文切换损耗：看起来很忙，实际更慢。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>发散和聚焦都重要，但顺序不能错：先用聚焦建立主线，再用发散补充视角。</p><p>前两天和同事交流“Orchestration vs Choreography”时，有聊到：</p><blockquote><p>Choreography 是 mesh 式的调用，其实是因为服务间相互不可知。即 Complex（Cynefin）的认知模式下，大家都是黑盒，因此只能依赖相邻的服务一步一步传递信息，实现业务的最终执行 Orchestration 则是由中心的指挥家总揽全局。因为整个系统对他而言处于 Clear 模式，需要谁做什么、谁先谁后，都心中有数。</p></blockquote><p>回到 Mesh-Shaped 的初衷，它不是“无限扩张的知识地图”，而是“以核心点为锚的可控扩展”。先守住核心域，再向外探索，学习系统才会稳定增值。</p><p><img src="'+l+'" alt="Orchestration vs Choreography"></p>',22)])])}const _=a(h,[["render",r]]);export{u as __pageData,_ as default};
